+
+const fs = require('node:fs');
+
+const args = process.argv.slice(2);
+if (args.length !== 1 || args[0].startsWith('-')) {
+  process.stderr.write('Usage: node bin/tally.js <file-path>\n');
+  process.exitCode = 1;
+} else {
