diff --git a/tests/tally.test.js b/tests/tally.test.js
new file mode 100644
index 0000000..9d629fd
--- /dev/null
+++ b/tests/tally.test.js
@@ -0,0 +1,51 @@
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const os = require('node:os');
+const path = require('node:path');
+const { spawnSync } = require('node:child_process');
+const { test } = require('node:test');
+
+const command = path.join(__dirname, '..', 'bin', 'tally.js');
+
+function runWithContents(contents) {
+  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'tally-'));
+  const file = path.join(directory, 'sample.txt');
+  try {
+    fs.writeFileSync(file, contents);
+    return spawnSync(process.execPath, [command, file], { encoding: 'utf8' });
+  } finally {
+    fs.rmSync(directory, { recursive: true, force: true });
+  }
+}
+
+test('counts words separated by spaces and line breaks', () => {
+  const result = runWithContents('one two\nthree');
+  assert.equal(result.status, 0);
+  assert.equal(result.stdout, '3\n');
+  assert.equal(result.stderr, '');
+});
+
+test('ignores repeated separators and returns zero for an empty file', () => {
+  assert.equal(runWithContents(' one  \n\n two ').stdout, '2\n');
+  assert.equal(runWithContents('').stdout, '0\n');
+});
+
+test('tabs are not word separators', () => {
+  assert.equal(runWithContents('one\ttwo three').stdout, '2\n');
+});
+
+test('rejects missing, extra, and flag arguments', () => {
+  for (const args of [[], ['a', 'b'], ['--lines'], ['--unknown']]) {
+    const result = spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
+    assert.notEqual(result.status, 0);
+    assert.equal(result.stdout, '');
+    assert.match(result.stderr, /Usage:/);
+  }
+});
+
+test('reports a missing file on standard error', () => {
+  const result = spawnSync(process.execPath, [command, path.join(os.tmpdir(), 'tally-file-does-not-exist')], { encoding: 'utf8' });
+  assert.notEqual(result.status, 0);
+  assert.equal(result.stdout, '');
+  assert.match(result.stderr, /Cannot read file:/);
+});

